 public function run(): void {
  $top=collect([['name'=>'Printed Stories','image'=>'https://images.unsplash.com/photo-1528459801416-a9e53bbf4e17?auto=format&fit=crop&w=900&q=85','description'=>'Expressive prints for every idea.'],['name'=>'Natural Linens','image'=>'https://images.unsplash.com/photo-1618220179428-22790b461013?auto=format&fit=crop&w=900&q=85','description'=>'Breathable texture, beautifully made.'],['name'=>'Cotton Essentials','image'=>'https://images.unsplash.com/photo-1504609813442-a8924e83f76e?auto=format&fit=crop&w=900&q=85','description'=>'Everyday comfort in colour.'],['name'=>'Occasion Edit','image'=>'https://images.unsplash.com/photo-1601924994987-69e26d50dc26?auto=format&fit=crop&w=900&q=85','description'=>'A little shimmer for the special days.']])->mapWithKeys(fn($c)=>[$c['name']=>Category::updateOrCreate(['slug'=>Str::slug($c['name'])],$c)]);
