  $products=[['Floral Dusk Cotton','Botanical',499,'https://images.unsplash.com/photo-1523693917688-1d0f2f2c29a9?auto=format&fit=crop&w=900&q=85','Rosewood','Cotton voile',1,1],['Indigo Mosaic Linen','European Linen',699,'https://images.unsplash.com/photo-1505751172876-fa1923c5c528?auto=format&fit=crop&w=900&q=85','Indigo','Pure linen',1,1],['Saffron Field Block Print','Abstract',579,'https://images.unsplash.com/photo-1590915828534-0f9c3f89bc2f?auto=format&fit=crop&w=900&q=85','Saffron','Cotton cambric',1,0],['Cloud White Cotton','Everyday Cotton',349,'https://images.unsplash.com/photo-1529139574466-a303027c1d8b?auto=format&fit=crop&w=900&q=85','Ivory','Organic cotton',1,0],['Emerald Garden Satin','Silk Satin',849,'https://images.unsplash.com/photo-1566206091558-7f218b696731?auto=format&fit=crop&w=900&q=85','Emerald','Silk satin',1,1],['Terracotta Check','Yarn Dyed',429,'https://images.unsplash.com/photo-1603252109303-2751441dd157?auto=format&fit=crop&w=900&q=85','Terracotta','Yarn dyed cotton',0,1],['Midnight Jacquard','Satin & Jacquard',1099,'https://images.unsplash.com/photo-1618221195710-dd6b41faaea6?auto=format&fit=crop&w=900&q=85','Midnight','Woven jacquard',0,1],['Petal Pink Linen','Linen Blends',729,'https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?auto=format&fit=crop&w=900&q=85','Blush','Linen blend',0,0]];
  foreach($products as [$name,$cat,$price,$image,$color,$material,$featured,$new]) Product::updateOrCreate(['slug'=>Str::slug($name)],['category_id'=>($leaf[$cat]??$sub[$cat])->id,'name'=>$name,'description'=>"A tactile, thoughtfully sourced {$material} crafted for garments, interiors and the everyday moments between.",'price'=>$price,'compare_at_price'=>$price+150,'image'=>$image,'color'=>$color,'material'=>$material,'width'=>'44 inches','stock'=>25,'is_featured'=>$featured,'is_new'=>$new]);
 }
